    "offen": "Offen",
    "angeboten": "Angeboten",
    "option": "Option",
    "ausgeschlossen": "Ausgeschlossen",
}
STORY_SCOPES: tuple[str, ...] = tuple(SCOPE_LABELS)

BOUND_FIELDS: dict[str, str] = {
    "offer.person_days": "Personentage",
    "offer.risk_buffer_days": "Risikopuffer (Personentage)",
    "offer.production_cost": "Herstellkosten",
    "offer.recommended_price": "Empfohlener Preis",
    "workspace.currency": "Währung",
    "workspace.validity_date": "Bindefrist",
}


class ContentValidationError(ValueError):
    """Chapter content violates the content model; messages are German."""

    def __init__(self, messages: list[str]) -> None:
        super().__init__("; ".join(messages))
        self.messages = messages


def _new_block_id() -> str:
    return uuid.uuid4().hex[:8]


class Run(BaseModel):
    text: str
    bold: bool = False
    italic: bool = False


Inline = list[Run]


class _Block(BaseModel):
    block_id: str = Field(default_factory=_new_block_id)


class Paragraph(_Block):
    type: Literal["paragraph"] = "paragraph"
    runs: Inline = Field(default_factory=list)


class Heading(_Block):
    type: Literal["heading"] = "heading"
    level: Literal[3, 4] = 3
    runs: Inline = Field(default_factory=list)


class BulletList(_Block):
    type: Literal["bullet_list"] = "bullet_list"
    items: list[Inline] = Field(default_factory=list)


class OrderedList(_Block):
    type: Literal["ordered_list"] = "ordered_list"
    items: list[Inline] = Field(default_factory=list)


class TableBlock(_Block):
    type: Literal["table"] = "table"
    header: list[Inline] = Field(min_length=1)
    rows: list[list[Inline]] = Field(default_factory=list)

    @field_validator("rows")
    @classmethod
    def _rows_match_header(
        cls, rows: list[list[Inline]], info: ValidationInfo
    ) -> list[list[Inline]]:
        _check_row_width(rows, len(info.data.get("header", [])), "die Kopfzeile")
        return rows


def _check_bound_field(value: str) -> str:
    if value not in BOUND_FIELDS:
        raise ValueError(f"Unbekannter Kalkulationswert: {value}")
    return value


BoundFieldName = Annotated[str, AfterValidator(_check_bound_field)]


def _check_row_width(rows: list[list[Inline]], width: int, what: str) -> None:
    if any(len(row) != width for row in rows):
        raise ValueError(
            f"Jede Tabellenzeile braucht genau so viele Zellen wie {what}."
        )


class BoundValue(_Block):
    type: Literal["bound_value"] = "bound_value"
            lines.extend(
                f"    {story['key']} [{story['scope']}] {story['title']}: "
                f"{story['sentence']}"
                for story in task["stories"]
                if not story["archived"]
            )
    return "\n".join(lines)


def _tags(text: str) -> str:
    """Neutralise angle brackets so text cannot close or open a delimiter."""
    return text.replace("<", "&lt;").replace(">", "&gt;")


def render_chapter(request: ChapterRequest, max_chars: int) -> str:
    """The chapter task with map and briefing as delimited data."""
    parts = [
        f'<kapitel titel="{_tags(request.title)}">',
        f"Leitfrage: {_tags(request.guiding_question)}",
        *(f"Regel: {_tags(rule)}" for rule in request.rules),
        "</kapitel>",
    ]
    if request.current_lines:
        lines = [_tags(line) for line in request.current_lines]
        parts += ["<aktueller_text>", *lines, "</aktueller_text>"]
    if request.instruction:
        parts += ["<anweisung>", _tags(request.instruction), "</anweisung>"]
    parts += ["<map>", _tags(request.map_outline)[:max_chars], "</map>"]
    parts += ["<briefing>", *map(_tags, request.statements), "</briefing>"]
    return "\n".join(parts)


def render_review(request: ReviewRequest, max_chars: int) -> str:
    """Map, briefing and chapters as delimited data for the review."""
    parts = ["<map>", _tags(request.map_outline), "</map>"]
    parts += ["<briefing>", *map(_tags, request.statements), "</briefing>"]
    for chapter in request.chapters:
        parts += [
            f'<kapitel key="{_tags(chapter.key)}" titel="{_tags(chapter.title)}">'
        ]
        parts += [*map(_tags, chapter.lines), "</kapitel>"]
    return "\n".join(parts)[:max_chars]


def render_map_request(request: MapRequest, max_chars: int) -> str:
    """Instruction, current map and briefing, then the sources as delimited data."""
    parts = ["<anweisung>", _tags(request.instruction), "</anweisung>"]
    parts += ["<map>", _tags(request.map_outline), "</map>"]
    parts += ["<briefing>", *map(_tags, request.statements), "</briefing>"]
    head = "\n".join(parts)
    sources = render_sources(request.sources, max(max_chars - len(head), 0))
    return f"{head}\n\n{sources}"

