async () => {
  window.__downloads = [];
  const orig = HTMLAnchorElement.prototype.click;
  HTMLAnchorElement.prototype.click = function () {
    window.__downloads.push({ name: this.download, href: (this.href || '').slice(0, 80), len: (this.href || '').length });
    return orig.call(this);
  };
  const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Word-Entwurf herunterladen'));
  btn.click();
  await new Promise(r => setTimeout(r, 4000));
  const toasts = [...document.querySelectorAll('[data-sonner-toast]')].map(t => t.textContent);
  return { downloads: window.__downloads, toasts };
}

